def access_check(token_sids, wanted, dacl):
    if dacl is None:                 # no DACL at all
        return "granted (no DACL: everyone gets full access)"
    granted = set()
    for ace in dacl:                 # in order, top to bottom
        if ace.sid not in token_sids:
            continue                 # ACE is about someone else
        if ace.kind == "deny" and ace.rights & wanted:
            return "denied"          # an explicit deny wins at once
        if ace.kind == "allow":
            granted |= ace.rights & wanted
            if granted == wanted:
                return "granted"
    return "denied (implicit)"       # empty DACL ends here too
